def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self.record.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._list.index(key)
    except ValueError:
        raise KeyError(f"{key} is not in the list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._data.values())
    else:
        result = []
        for key in keys:
            try:
                result.append(self._data[key])
            except KeyError:
                try:
                    result.append(self._data[list(self._data.keys())[key]])
                except IndexError:
                    raise KeyError(f"Key or index '{key}' not found in the record.")
        return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._fields)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._fields):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields.keys()[key]] = self._fields.values()[key]
        elif isinstance(key, str):
            result[key] = self._fields.get(key, None)
        else:
            raise TypeError(f"Invalid key type: {type(key)}")

    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        from shapely.geometry import Point as ShapelyPoint

        class DynamicPoint(ShapelyPoint):
            __name__ = name

            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                for field, value in kwargs.items():
                    if field in fields:
                        setattr(self, field, value)
                self.srid = srid_map.get(self.__class__.__name__, None)

        return DynamicPoint
    except ImportError:
        raise ImportError("Shapely library is required to create a Point subclass.")
    except Exception as e:
        raise Exception(f"An error occurred while creating the Point subclass: {e}")

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

