def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        # Extract all digests present in the manifest files
        digests_present = set()
        for manifest_file in manifest_files:
            if not isinstance(manifest_file, dict):
                raise ValueError("Each manifest file should be a dictionary.")
            digests_present.update(manifest_file.get('digests', {}).keys())

        # Check if all digests used are present in the manifest
        for digest in digests_used:
            if digest not in digests_present:
                raise ValueError(f"Digest {digest} is used but not present in the manifest.")

    except Exception as e:
        raise ValueError(f"Error checking digests: {str(e)}")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    try:
        for item in inventory.get_items(version):
            logical_path = item.get_logical_path()
            content_file = item.get_content_file()
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)
    except Exception as e:
        raise ValueError(f"Error processing inventory for version {version}: {e}")
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    manifest_files_set = set(manifest_files)

    for file_ref in fixity:
        if file_ref not in manifest_files_set:
            raise ValueError(f"File '{file_ref}' in fixity block is not listed in the manifest.")

        file_info = fixity[file_ref]
        if not isinstance(file_info, dict):
            raise ValueError(f"Fixity information for '{file_ref}' must be a dictionary.")

        if 'checksum' not in file_info:
            raise ValueError(f"Fixity information for '{file_ref}' must include a 'checksum'.")

        if 'algorithm' not in file_info:
            raise ValueError(f"Fixity information for '{file_ref}' must include an 'algorithm'.")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        raise FileNotFoundError(f"The path {path} does not exist.")
    except PermissionError:
        raise PermissionError(f"Permission denied to access the path {path}.")
    except Exception as e:
        raise Exception(f"An error occurred while accessing the path {path}: {e}")

def add_rendition(self, lang, file_path):
    """
    Adds a rendition for a specific language.

    Parameters:
        lang (str): The language code.
        file_path (str): The file path of the rendition.

    Raises:
        ValueError: If the language code or file path is invalid.
    """
    if not isinstance(lang, str) or not lang:
        raise ValueError("Language code must be a non-empty string.")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("File path must be a non-empty string.")

    if not hasattr(self, 'renditions'):
        self.renditions = {}

    self.renditions[lang] = file_path

def add_asset(self, basename, file_path):
    """
    Adds an asset to the internal dictionary with the given basename and file path.

    Parameters:
        basename (str): The basename of the asset file.
        file_path (str): The file path of the asset.

    Raises:
        ValueError: If the basename or file_path is not a string or if the basename already exists in the assets.
    """
    if not isinstance(basename, str) or not isinstance(file_path, str):
        raise ValueError("Both basename and file_path must be strings.")

    if hasattr(self, 'assets'):
        if basename in self.assets:
            raise ValueError(f"An asset with the basename '{basename}' already exists.")
        self.assets[basename] = file_path
    else:
        self.assets = {basename: file_path}

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise ValueError("Content must be a string")

    try:
