def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            match = node.xpath(xpath)
            if match:
                return match[0]
        except Exception as e:
            # Handle any exceptions that may occur during xpath evaluation
            print(f"An error occurred while evaluating xpath '{xpath}': {e}")
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}{self.__class__.__name__}(\n"
        for key, value in self.__dict__.items():
            if isinstance(value, list):
                result += f"{indent_str}  {key}=[\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        result += item.pretty(indent + 2, debug) + ",\n"
                    else:
                        result += f"{indent_str}    {item},\n"
                result += f"{indent_str}  ],\n"
            elif hasattr(value, 'pretty'):
                result += f"{indent_str}  {key}={value.pretty(indent + 2, debug)},\n"
            else:
                result += f"{indent_str}  {key}={value},\n"
        result += f"{indent_str})"
        return result
    except Exception as e:
        if debug:
            return f"{indent_str}Error formatting {self.__class__.__name__}: {str(e)}"
        else:
            return f"{indent_str}{self.__class__.__name__}()"

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

