def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise ValueError("pieces must be a list")
    if not isinstance(style, str):
        raise ValueError("style must be a string")

    if style == 'numeric':
        return '.'.join(map(str, pieces))
    elif style == 'dotted':
        return '.'.join(map(str, pieces))
    elif style == 'hyphenated':
        return '-'.join(map(str, pieces))
    elif style == 'plain':
        return ''.join(map(str, pieces))
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list) or not commands:
        raise ValueError("Commands must be a non-empty list.")
    if not isinstance(args, list):
        raise ValueError("Arguments must be a list.")
    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("Current working directory must be a valid directory path.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment variables must be provided as a dictionary.")

    full_command = commands + args
    if verbose:
        print("Running command:", ' '.join(full_command))

    try:
        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
            if verbose:
                print("Command output:", output)
            return output
    except Exception as e:
        if verbose:
            print("An error occurred:", str(e))
        raise

def register_vcs_handler(vcs, method):  # decorator
