def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for obj in self.iter_objects():
            num_objects += 1
            is_valid = True
            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} is not valid.")
            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for object {obj}.")
            if is_valid:
                good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Error during validation: {e}")

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    root_inventory = self.get_root_inventory()
    content_digests = {}

    for version_dir in version_dirs:
        try:
            version_inventory = self.get_inventory(version_dir)
        except FileNotFoundError:
            print(f"Warning: Inventory for version {version_dir} not found.")
            continue
        except Exception as e:
            print(f"Error reading inventory for version {version_dir}: {e}")
            continue

        for item, digest in version_inventory.items():
            if item in root_inventory:
                if digest != root_inventory[item]:
                    if item not in content_digests:
                        content_digests[item] = set()
                    content_digests[item].add(digest)
            else:
                print(f"Warning: Item {item} in version {version_dir} inventory not found in root inventory.")

    for item, digests in content_digests.items():
        if len(digests) > 1:
            print(f"Warning: Inconsistent digests for item {item}: {digests}")

    return content_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            namaste_file = os.path.join(path, '0=ocfl_1.0')
            if os.path.isfile(namaste_file):
                return 'root'
            else:
                for item in os.listdir(path):
                    item_path = os.path.join(path, item)
                    if os.path.isdir(item_path):
                        namaste_file = os.path.join(item_path, '0=ocfl_object_1.0')
                        if os.path.isfile(namaste_file):
                            return 'object'
        return 'unknown directory structure'
    except Exception as e:
        return str(e)

