def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, str):
        return re.sub(r'^["\']|["\']$', '', name)
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # POSIX shell-like syntax
        pattern = r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+"""
    elif platform == 0:  # Windows/CMD
        # Windows CMD-like syntax
        pattern = r"""(["'])(?:(?=(\\?))\2.)*?\1|\S+"""
    else:
        raise ValueError("Unsupported platform value")

    def replace_escaped(match):
        s = match.group(0)
        if s[0] in "\"'":
            return re.sub(r'\\(.)', r'\1', s[1:-1])
        return s

    return [replace_escaped(m) for m in re.finditer(pattern, s)]

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid frequency format: {frequency}")

        value = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=value)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=value)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=value)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=value)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=value)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid frequency: {frequency}") from e

