def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred during Gaussian calculation: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)
                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            config.set(section, key, os.path.expandvars(value))
                config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(record)

    # Apply overrides
    for section, options in overrides.items():
        for key, value in options.items():
            for config in config_dict.values():
                if config.has_section(section):
                    config.set(section, key, value)

    return config_dict, log_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    elif isinstance(obj, bytes):
        return obj
    else:
        raise ValueError("Input must be a string or bytes object")

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if not isinstance(values, Iterable):
        raise ValueError("Values must be an iterable of strings.")

    bookmarks = []
    for value in values:
        if not isinstance(value, str):
            raise ValueError("Each value must be a string.")
        bookmarks.append(value.strip())

    return cls(bookmarks)

