def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    import requests
    try:
        response = requests.head(url, allow_redirects=True)
        response.raise_for_status()
        return response.headers.get('Content-Type')
    except requests.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise ValueError("The tag must be a string.")
    if not tag:
        return False
    if not tag[0].isalnum():
        return False
    if not all(c.isalnum() or c in '-._' for c in tag):
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        if child.tag in result:
            raise ValueError(f"Duplicate tag found: {child.tag}")
        result[child.tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender_handle and entity_handle must be provided.")

    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle ({sender_handle}) and entity handle ({entity_handle}) do not match.")

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url:
        raise ValueError("The URL must be a non-empty string.")

    if document_path and not isinstance(document_path, str):
        raise ValueError("The document_path must be a string if provided.")

    base_url = url.rstrip('/')
    nodeinfo_path = document_path if document_path else '/.well-known/nodeinfo'
    links = [
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
            "href": f"{base_url}{nodeinfo_path}?version=2.0"
        },
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
            "href": f"{base_url}{nodeinfo_path}?version=2.1"
        }
    ]

    return {
        "links": links
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try parsing as XRD XML
            root = ET.fromstring(document)
            result = {}
            for element in root.findall('.//xrd:Property', namespaces={'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}):
                name = element.get('type')
                value = element.text
                if name and value:
                    result[name] = value
            return result
        except ET.ParseError:
            raise ValueError("Document is not in valid JSON or XRD format")
        except Exception as e:
            raise ValueError(f"Error parsing XRD document: {str(e)}")
    except Exception as e:
        raise ValueError(f"Error parsing JSON document: {str(e)}")

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import json

    if not isinstance(handle, str) or not handle:
        raise ValueError("Handle must be a non-empty string")

    try:
        response = requests.get(f"https://diaspora.example.com/.well-known/webfinger?resource=acct:{handle}")
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")

    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise Exception(f"Failed to parse webfinger document: {e}")

    if not isinstance(data, dict):
        raise Exception("Webfinger document is not a valid JSON object")

    return data

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xrd import XRD

    try:
        response = requests.get(f"https://{host}/.well-known/host-meta")
        response.raise_for_status()
        return XRD(response.text)
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Failed to retrieve host-meta from {host}: {e}")
    except Exception as e:
        raise ValueError(f"Error parsing host-meta from {host}: {e}")

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        if not isinstance(settings_dirs, list):
            raise ValueError("settings_dirs must be a list")
        if not isinstance(spec_option, str):
            raise ValueError("spec_option must be a string")

        file_names = []
        for directory in settings_dirs:
            if not isinstance(directory, str):
                raise ValueError("Each item in settings_dirs must be a string representing a directory path")
            try:
                import os
                for entry in os.listdir(directory):
                    full_path = os.path.join(directory, entry)
                    if os.path.isfile(full_path):
                        file_names.append(entry)
            except FileNotFoundError:
                raise FileNotFoundError(f"The directory {directory} does not exist")
            except PermissionError:
                raise PermissionError(f"Permission denied to access the directory {directory}")

        return file_names

    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

