@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml
    from os.path import exists

    if not yaml_file or not isinstance(yaml_file, str):
        raise ValueError("yaml_file must be a valid file path string")

    if not exists(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_file, 'r', encoding='utf-8') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file {yaml_file} does not contain a valid dictionary")

    required_fields = {'name', 'version', 'description'}  # Example required fields, adjust as necessary
    missing_fields = required_fields - data.keys()

    if missing_fields:
        raise IRValidatorException(f"Missing required fields in {yaml_file}: {', '.join(missing_fields)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_directive = parser_dict.pop('include')
    if not isinstance(include_directive, list):
        raise ValueError("include directive must be a list")

    for group in include_directive:
        if not isinstance(group, str):
            raise ValueError("Each include group must be a string")
        # Assuming there's a method to fetch the group by name
        included_group = self._fetch_group_by_name(group)
        if included_group is None:
            raise ValueError(f"Group '{group}' not found")
        parser_dict.update(included_group)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        defaults = {}
        for arg, spec in self.spec.items():
            if 'default' in spec:
                defaults[arg] = spec['default']
            elif 'required' in spec and not spec['required']:
                defaults[arg] = None
        return defaults
    except Exception as e:
        raise ValueError(f"Error resolving default values from spec: {e}")

