def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'required_args'):
        raise AttributeError("Class does not have a 'required_args' attribute defined.")

    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    missing_args = [arg for arg in self.required_args if arg not in args]

    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            condition = required_when.get('condition')
            if condition:
                try:
                    if eval(condition, {}, args):
                        matched_args.append(option.get('name'))
                except Exception as e:
                    # Handle potential issues with the condition evaluation
                    print(f"Error evaluating condition for {option.get('name')}: {e}")
    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        if isinstance(arg_value, str) and hasattr(self, f"max_length_{arg_name}"):
            max_length = getattr(self, f"max_length_{arg_name}")
            if len(arg_value) > max_length:
                raise ValueError(f"The length of '{arg_name}' exceeds the maximum allowed length of {max_length}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if hasattr(self, f'{arg_name}_choices'):
            choices = getattr(self, f'{arg_name}_choices')
            if arg_value not in choices:
                raise ValueError(f"Invalid value for {arg_name}: {arg_value}. Must be one of {choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min_max_values'):
        raise AttributeError("Class must have a 'min_max_values' attribute defined.")

    for arg_name, value in args.items():
        if arg_name in self.min_max_values:
            min_val, max_val = self.min_max_values[arg_name]
            if value < min_val or value > max_val:
                raise ValueError(f"Argument '{arg_name}' is out of bounds. Expected value between {min_val} and {max_val}, got {value}.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    try:
        for arg, value in args.items():
            if arg.startswith('control_'):
                control_args[arg[len('control_'):]] = value
            elif arg.startswith('custom_'):
                custom_args[arg[len('custom_'):]] = value
            else:
                nested_args[arg] = value
    except AttributeError:
        raise ValueError("Arguments must be provided as a dictionary.")

    return control_args, nested_args

@staticmethod
